// eslint-disable
'use strict';

const logger = require('@yandex-int/yandex-logger')({
    name: 'my-logger',

    // Настраиваем стримы, в которые будем отправлять логи
    streams: [
        // Логируем все сообщения в stdout
        {
            level: 'info',
            stream: require('@yandex-int/yandex-logger/streams/json')(process.stdout),
        },

        // Дополнительно логируем ошибки в stderr
        {
            level: 'error',
            stream: require('@yandex-int/yandex-logger/streams/json')(process.stderr),
        },
    ],

    // Добавляем свои middleware
    middleware: [
        require('@yandex-int/yandex-logger/middleware/preset-default')(),

        record => {
            record.something = 'value';
            record.method = record.method || 'GET';
        },
    ],

    // Дополнительные поля для всех записей в логах
    fields: {
        release: '7.0.0',
        tags: {
            host: require('os').hostname(),
        },
    },
});

// 1. Простое сообщение
logger.info('Log message');

// 2. Логируем только ошибку
let err = new Error('Something went wrong!');
logger.error(err);

// 3. Логируем ошибку и дополнительную информацию о запросе
let req = require('./entry').req;
logger.error({
    req,
    err,
});
